public class EnhancedForDemo {
    public static void main(String[] args) {
        String[] companies = {"Google", "Amazon", "Oracle", "Microsoft"};

        System.out.println("--- Reading with Enhanced for Loop ---");
        for (String company : companies) {
            System.out.println("Company: " + company);
        }

        System.out.println("\n--- The Local Copy Modification Trap ---");
        int[] scores = {1, 2, 3};
        for (int val : scores) {
            val = val * 10; // Changes ONLY the local copy 'val'!
        }

        // scores is STILL {1, 2, 3}!
        System.out.println("scores[0] is still: " + scores[0]); // 1
    }
}

