practiceProblems.solutionCode:
public class Main {
    public static int countEvens(int[] nums) {
        int count = 0;
        for (int n : nums) {
            if (n % 2 == 0) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[] data = {14, 7, 22, 33, 40, 51};
        System.out.println("Even Count: " + countEvens(data));
    }
}

