practiceProblems.solutionCode:
public class Main {
    public static boolean contains(String[] list, String target) {
        for (String item : list) {
            if (item.equals(target)) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        String[] fruits = {"apple", "banana", "pear"};
        System.out.println("Contains banana: " + contains(fruits, "banana"));
        System.out.println("Contains orange: " + contains(fruits, "orange"));
    }
}

