practiceProblems.solutionCode:
public class Main {
    public static void printHighScores(int[] scores, int threshold) {
        for (int s : scores) {
            if (s >= threshold) {
                System.out.println("High Score: " + s);
            }
        }
    }

    public static void main(String[] args) {
        int[] scores = {65, 88, 72, 95, 82};
        printHighScores(scores, 80);
    }
}
